import { timingSafeEqual } from 'node:crypto';

export interface SiteAuthEnv {
  DB?: D1Database;
  // Exclusively a cryptographically random 256-bit password generated by the
  // setup script. This format does not support human-chosen passwords.
  ADMIN_PASSWORD_HASH?: string;
}
export const ADMIN_COOKIE = '__Host-site-admin';
export const ADMIN_SESSION_SECONDS = 8 * 60 * 60;

export function authConfigured(env: SiteAuthEnv): boolean {
  return /^[a-f0-9]{64}$/.test(env.ADMIN_PASSWORD_HASH ?? '');
}
export async function digest(value: string): Promise<string> {
  const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return Array.from(new Uint8Array(hash), n => n.toString(16).padStart(2, '0')).join('');
}
export async function passwordMatches(value: string, env: SiteAuthEnv): Promise<boolean> {
  if (!authConfigured(env) || value.length > 256) return false;
  const candidate = await digest(value);
  const bytes = (hex: string) => Uint8Array.from(hex.match(/../g)!, value => parseInt(value, 16));
  return timingSafeEqual(bytes(candidate), bytes(env.ADMIN_PASSWORD_HASH!));
}
export function sessionToken(request: Request): string | null {
  const entries = (request.headers.get('Cookie') ?? '').split(';').map(value => value.trim());
  const matching = entries.filter(value => value.startsWith(ADMIN_COOKIE + '='));
  if (matching.length !== 1) return null;
  const value = matching[0]!.slice(ADMIN_COOKIE.length + 1);
  return /^[A-Za-z0-9_-]{43}$/.test(value) ? value : null;
}
export function sessionCookie(token: string, seconds = ADMIN_SESSION_SECONDS): string {
  return `${ADMIN_COOKIE}=${token}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=${seconds}`;
}
function randomToken(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
export async function isSiteAdmin(request: Request, env: SiteAuthEnv): Promise<boolean> {
  if (!authConfigured(env) || !env.DB) return false;
  const token = sessionToken(request);
  if (!token) return false;
  const session = await env.DB.prepare('SELECT expires_at,password_version,hostname FROM site_admin_sessions WHERE token_hash=?').bind(await digest(token)).first<{expires_at:number; password_version:string; hostname:string}>();
  return Boolean(session && session.expires_at > Date.now() && session.password_version === env.ADMIN_PASSWORD_HASH && session.hostname === new URL(request.url).hostname);
}
export async function createAdminSession(request: Request, env: SiteAuthEnv): Promise<string> {
  if (!env.DB || !authConfigured(env)) throw new Error('Admin authentication is not configured');
  const token = randomToken(), previous = sessionToken(request);
  const statements: D1PreparedStatement[] = [];
  if (previous) statements.push(env.DB.prepare('DELETE FROM site_admin_sessions WHERE token_hash=?').bind(await digest(previous)));
  statements.push(
    env.DB.prepare('INSERT INTO site_admin_sessions(token_hash,expires_at,password_version,hostname) VALUES (?,?,?,?)').bind(await digest(token), Date.now() + ADMIN_SESSION_SECONDS * 1000, env.ADMIN_PASSWORD_HASH!, new URL(request.url).hostname),
    env.DB.prepare('DELETE FROM site_admin_sessions WHERE expires_at<=?').bind(Date.now()),
    env.DB.prepare('DELETE FROM site_admin_login_limits WHERE expires_at<=?').bind(Date.now())
  );
  await env.DB.batch(statements);
  return token;
}
export async function revokeAdminSession(request: Request, env: SiteAuthEnv): Promise<void> {
  const token = sessionToken(request);
  if (token && env.DB) await env.DB.prepare('DELETE FROM site_admin_sessions WHERE token_hash=?').bind(await digest(token)).run();
}
export async function allowLogin(request: Request, env: SiteAuthEnv): Promise<boolean> {
  if (!env.DB || !authConfigured(env)) return false;
  const ip = request.headers.get('CF-Connecting-IP');
  if (!ip) return false;
  const window = Math.floor(Date.now() / (15 * 60 * 1000));
  const bucket = await digest(env.ADMIN_PASSWORD_HASH + ':' + ip + ':' + window);
  const limited = await env.DB.prepare('INSERT INTO site_admin_login_limits(bucket,count,expires_at) VALUES (?,1,?) ON CONFLICT(bucket) DO UPDATE SET count=count+1 RETURNING count').bind(bucket, (window + 2) * 15 * 60 * 1000).first<{count:number}>();
  return Boolean(limited && limited.count <= 5);
}
